"""Every case in conformance/validation.v1.json, generated by the TypeScript validators."""

import json
import unittest
from pathlib import Path
from typing import Any

from super_editor.validation import Invalid, read_actor, safe_url, timestamp, validate_document, validate_transaction

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "validation.v1.json").read_text())


def verdict(kind: str, value: Any) -> dict[str, Any]:
    if kind == "document":
        return validate_document(value)
    if kind == "transaction":
        return validate_transaction(value)
    try:
        if kind == "actor":
            return {"ok": True, "value": read_actor(value)}
        return {"ok": True, "value": timestamp(value)}
    except Invalid as error:
        return {"ok": False, "issues": [error.issue]}


class Validation(unittest.TestCase):
    def test_cases(self) -> None:
        self.assertGreaterEqual(len(DATA["cases"]), 1000)
        for i, case in enumerate(DATA["cases"]):
            with self.subTest(i=i, kind=case["kind"]):
                if case["kind"] == "url":
                    got = safe_url(case["input"])
                    want = None if case.get("portRejects") or not case["expect"]["ok"] else case["expect"]["value"]
                    self.assertEqual(got, want)
                    continue
                self.assertEqual(verdict(case["kind"], case["input"]), case["expect"])


if __name__ == "__main__":
    unittest.main()
